INSERT INTO `phuc_loi` (`id`, `name`, `max_tab`, `id_tab`, `info_phucloi`, `action`) VALUES
(0, 'Nạp Tích Lũy', 8, 0, '- Khi nạp Coin tại Web bạn sẽ được tích lũy điểm các Mốc.\r\n-Khi đạt đủ điểm sẽ nhận được các phần thưởng của từng mốc nạp.\r\n-Các phần quà chỉ được nhận 1 lần khi sự kiện đang diễn ra !!!!', 1),
